1	/// The Room screen's presentation: top bar, stage, rail, dock, toast. Fed a [RoomViewData]
2	/// snapshot and callbacks, so it renders without a socket or a native player.
3	library;
4	
5	import 'dart:async';
6	import 'dart:math' as math;
7	
8	import 'package:flutter/material.dart';
9	import 'package:flutter/services.dart';
10	
11	import 'format.dart';
12	import 'player.dart' show seekAtMs;
13	import 'room_controls.dart';
14	import 'theme.dart';
15	import 'widgets/button.dart';
16	import 'widgets/chrome.dart';
17	import 'widgets/identity.dart';
18	
19	/// Stage shape for scope files; everything else gets a 16:9 stage.
20	const double scopeAspect = 2.39;
21	
22	/// 16:9, or 2.39:1 when the file is scope-wide; the picture letterboxes inside, never stretched.
23	double stageAspect(double fileAspect) =>
24	    fileAspect >= (16 / 9 + scopeAspect) / 2 ? scopeAspect : 16 / 9;
25	
26	/// The video stage box, for layout tests.
27	const Key roomStageKey = ValueKey('room-stage');
28	
29	/// The dock, for the fullscreen auto-hide tests.
30	const Key roomDockKey = ValueKey('room-dock');
31	
32	/// Fullscreen chrome (dock, exit button, cursor) hides after this long without pointer movement.
33	const Duration chromeHideAfter = Duration(milliseconds: 2500);
34	
35	enum PersonState { synced, buffering, drifting, noFile, reconnecting }
36	
37	class RoomPerson {
38	  const RoomPerson({
39	    required this.id,
40	    required this.name,
41	    this.you = false,
42	    this.host = false,
43	    this.state = PersonState.synced,
44	    this.driftMs = 0,
45	  });
46	  final String id;
47	  final String name;
48	  final bool you;
49	  final bool host;
50	  final PersonState state;
51	  final double driftMs;
52	
53	  /// Synced, or drifting within the seek threshold (the player is still nudging it in).
54	  bool get ready => switch (state) {
55	    PersonState.synced => true,
56	    PersonState.drifting => driftMs.abs() < seekAtMs,
57	    PersonState.buffering ||
58	    PersonState.noFile ||
59	    PersonState.reconnecting => false,
60	  };
61	
62	  String get status => switch (state) {
63	    PersonState.synced => 'Synced',
64	    PersonState.buffering => 'Buffering',
65	    PersonState.drifting =>
66	      'Drifting ${driftMs < 0 ? '−' : '+'}${(driftMs.abs() / 1000).round()}s',
67	    PersonState.noFile => 'No file',
68	    PersonState.reconnecting => 'Reconnecting',
69	  };
70	}
71	
72	/// The ready pill's tooltip: who is not ready, and why.
73	String readyDetail(List<RoomPerson> people) {
74	  final waiting = people.where((p) => !p.ready).toList();
75	  if (waiting.isEmpty) return 'Everyone has the file and is in sync.';
76	  return [
77	    'Not ready yet',
78	    for (final p in waiting) '${p.name}${p.you ? ' (you)' : ''} · ${p.status}',
79	  ].join('\n');
80	}
81	
82	enum StageMode { empty, waiting, video }
83	
84	/// Where a copy comes from: a file on disk, or a stream from the viewer's Jellyfin.
85	enum MediaSource { local, jellyfin }
86	
87	/// `In sync`, or `Adjusting` while the drift policy is correcting.
88	enum SyncState { inSync, adjusting }
89	
90	typedef QueueRow = ({String title, String detail});
91	
92	/// Shown as a toast, then named on the stage while playback stays paused.
93	class PauseNotice {
94	  const PauseNotice({required this.serial, required this.positionMs, this.by});
95	  final int serial;
96	  final int positionMs;
97	
98	  /// Who paused, when known (`You`, or the only other person).
99	  final String? by;
100	}
101	
102	class RoomViewData {
103	  const RoomViewData({
104	    required this.room,
105	    this.title = 'Room',
106	    this.invite,
107	    this.connected = true,
108	    this.connecting = false,
109	    this.disconnectReason,
110	    this.people = const [],
111	    this.nowPlaying,
112	    this.upNext = const [],
113	    this.stage = StageMode.empty,
114	    this.mismatch = false,
115	    this.opening = false,
116	    this.buffering = false,
117	    this.error,
118	    this.ended = false,
119	    this.waitingFor,
120	    this.fileName,
121	    this.source,
122	    this.roomSource,
123	    this.positionMs = 0,
124	    this.durationMs = 0,
125	    this.bufferedMs = 0,
126	    this.playing = false,
127	    this.aspect = 16 / 9,
128	    this.muted = false,
129	    this.volume = 100,
130	    this.rate = 1,
131	    this.sync,
132	    this.driftMs,
133	    this.audioTracks = const [],
134	    this.subtitleTracks = const [],
135	    this.fullscreen = false,
136	    this.pause,
137	  });
138	  final String room;
139	  final String title;
140	  final String? invite;
141	  final bool connected;
142	
143	  /// Not connected yet for the first time, as opposed to dropped.
144	  final bool connecting;
145	
146	  /// Set when the connection is gone for good (bad token, room ended); otherwise we retry.
147	  final String? disconnectReason;
148	  final List<RoomPerson> people;
149	
150	  /// The room's item; null while nobody has pressed play.
151	  final QueueRow? nowPlaying;
152	  final List<QueueRow> upNext;
153	  final StageMode stage;
154	
155	  /// In [StageMode.waiting]: a file is open but it is not the room's file.
156	  final bool mismatch;
157	
158	  /// Our copy is being hashed or loaded; [fileName] names it.
159	  final bool opening;
160	
161	  /// The player is waiting for data.
162	  final bool buffering;
163	
164	  /// Why our copy failed to open or play, in words for the error card.
165	  final String? error;
166	
167	  /// Our copy reached its end.
168	  final bool ended;
169	
170	  /// Who the room waits on to press play: a name, `You`, or null when nobody can tell.
171	  final String? waitingFor;
172	
173	  /// Our copy's display name (a Jellyfin copy's picked title, never its URL).
174	  final String? fileName;
175	
176	  /// Where our copy comes from; null without one.
177	  final MediaSource? source;
178	
179	  /// Where the room's item comes from, for the right "open that file" action.
180	  final MediaSource? roomSource;
181	  final int positionMs;
182	  final int durationMs;
183	  final int bufferedMs;
184	  final bool playing;
185	  final double aspect;
186	  final bool muted;
187	
188	  /// 0–100, kept while muted.
189	  final double volume;
190	
191	  /// The room's chosen speed. Never the drift engine's nudged rate.
192	  final double rate;
193	  final SyncState? sync;
194	
195	  /// Player minus room, for the sync tooltip.
196	  final double? driftMs;
197	  final List<TrackOption> audioTracks;
198	
199	  /// Includes `Off` when the player reports subtitles.
200	  final List<TrackOption> subtitleTracks;
201	  final bool fullscreen;
202	  final PauseNotice? pause;
203	
204	  int get readyCount => people.where((p) => p.ready).length;
205	}
206	
207	class RoomView extends StatefulWidget {
208	  const RoomView({
209	    super.key,
210	    required this.data,
211	    required this.video,
212	    this.onBack,
213	    this.onOpenFile,
214	    this.onOpenJellyfin,
215	    this.onPlay,
216	    this.onPause,
217	    this.onSeekBy,
218	    this.onSeekTo,
219	    this.onToggleMute,
220	    this.onVolume,
221	    this.onFullscreen,
222	    this.onSettings,
223	    this.onAddToQueue,
224	    this.onRetry,
225	    this.onReplay,
226	    this.onPlayNext,
227	    this.onAudioTrack,
228	    this.onSubtitleTrack,
229	  });
230	  final RoomViewData data;
231	  final Widget video;
232	  final VoidCallback? onBack;
233	  final VoidCallback? onOpenFile;
234	
235	  /// Pick a Jellyfin item instead of a local file; null hides the option.
236	  final VoidCallback? onOpenJellyfin;
237	  final VoidCallback? onPlay;
238	  final VoidCallback? onPause;
239	  final ValueChanged<int>? onSeekBy;
240	  final ValueChanged<int>? onSeekTo;
241	  final VoidCallback? onToggleMute;
242	  final ValueChanged<double>? onVolume;
243	  final VoidCallback? onFullscreen;
244	  final VoidCallback? onSettings;
245	  final VoidCallback? onAddToQueue;
246	
247	  /// Open the copy that failed again.
248	  final VoidCallback? onRetry;
249	
250	  /// Play the room's item from the start.
251	  final VoidCallback? onReplay;
252	
253	  /// Move the room to the head of the queue.
254	  final VoidCallback? onPlayNext;
255	  final ValueChanged<String>? onAudioTrack;
256	  final ValueChanged<String>? onSubtitleTrack;
257	
258	  @override
259	  State<RoomView> createState() => _RoomViewState();
260	}
261	
262	class _RoomViewState extends State<RoomView> {
263	  final _playLink = LayerLink();
264	  bool _toast = false;
265	  Timer? _toastTimer;
266	  bool _copied = false;
267	  Timer? _copyTimer;
268	
269	  /// The rail as an overlay sheet, below [wtCompactWidth].
270	  bool _sheet = false;
271	
272	  /// Fullscreen chrome auto-hide. Only a real pointer arms it, so a window nobody has pointed
273	  /// at (and every widget test) keeps its controls.
274	  bool _idle = false;
275	  bool _pointerSeen = false;
276	  bool _overChrome = false;
277	  Timer? _idleTimer;
278	
279	  RoomViewData get _d => widget.data;
280	  bool get _hasFile => _d.stage == StageMode.video;
281	  bool get _live => _hasFile && _d.connected;
282	  bool get _chromeHidden => _d.fullscreen && _idle;
283	
284	  @override
285	  void didUpdateWidget(RoomView old) {
286	    super.didUpdateWidget(old);
287	    final notice = _d.pause;
288	    if (notice == null) {
289	      _hideToast();
290	    } else if (notice.serial != old.data.pause?.serial) {
291	      _toastTimer?.cancel();
292	      _toast = true;
293	      _toastTimer = Timer(const Duration(seconds: 4), _hideToast);
294	    }
295	    if (old.data.fullscreen != _d.fullscreen ||
296	        old.data.playing != _d.playing) {
297	      _idle = false;
298	      _armIdle();
299	    }
300	  }
301	
302	  @override
303	  void dispose() {
304	    _toastTimer?.cancel();
305	    _copyTimer?.cancel();
306	    _idleTimer?.cancel();
307	    super.dispose();
308	  }
309	
310	  void _hideToast() {
311	    _toastTimer?.cancel();
312	    if (_toast && mounted) setState(() => _toast = false);
313	  }
314	
315	  void _copyInvite() {
316	    Clipboard.setData(ClipboardData(text: _d.invite ?? _d.room));
317	    setState(() => _copied = true);
318	    _copyTimer?.cancel();
319	    _copyTimer = Timer(const Duration(milliseconds: 1500), () {
320	      if (mounted) setState(() => _copied = false);
321	    });
322	  }
323	
324	  void _wake() {
325	    if (_idle) setState(() => _idle = false);
326	    _armIdle();
327	  }
328	
329	  /// Hides the chrome after [chromeHideAfter] in fullscreen, while playing and not over a control.
330	  void _armIdle() {
331	    _idleTimer?.cancel();
332	    if (!_d.fullscreen || !_pointerSeen) return;
333	    _idleTimer = Timer(chromeHideAfter, () {
334	      if (!mounted || !_d.fullscreen || !_d.playing || _overChrome) return;
335	      setState(() => _idle = true);
336	    });
337	  }
338	
339	  void _chromeHover(bool over) {
340	    _overChrome = over;
341	    if (!over) _armIdle();
342	  }
343	
344	  void _showShortcuts() => showShortcutSheet(context);
345	
346	  VoidCallback? get _playPause =>
347	      !_live ? null : (_d.playing ? widget.onPause : widget.onPlay);
348	
349	  VoidCallback? _seek(int delta) =>
350	      _live && widget.onSeekBy != null ? () => widget.onSeekBy!(delta) : null;
351	
352	  /// Why the transport is off, for its tooltips; null while it works.
353	  String? get _offReason => !_hasFile
354	      ? 'open a file first'
355	      : !_d.connected
356	      ? 'reconnecting'
357	      : null;
358	
359	  @override
360	  Widget build(BuildContext context) {
361	    void run(VoidCallback? f) {
362	      _wake();
363	      f?.call();
364	    }
365	
366	    return CallbackShortcuts(
367	      bindings: {
368	        const SingleActivator(LogicalKeyboardKey.space): () => run(_playPause),
369	        const SingleActivator(LogicalKeyboardKey.arrowLeft): () =>
370	            run(_seek(-arrowSeekMs)),
371	        const SingleActivator(LogicalKeyboardKey.arrowRight): () =>
372	            run(_seek(arrowSeekMs)),
373	        const SingleActivator(LogicalKeyboardKey.arrowLeft, shift: true): () =>
374	            run(_seek(-longSeekMs)),
375	        const SingleActivator(LogicalKeyboardKey.arrowRight, shift: true): () =>
376	            run(_seek(longSeekMs)),
377	        const SingleActivator(LogicalKeyboardKey.keyF): () =>
378	            run(_hasFile ? widget.onFullscreen : null),
379	        const SingleActivator(LogicalKeyboardKey.keyM): () =>
380	            run(_hasFile ? widget.onToggleMute : null),
381	        const SingleActivator(LogicalKeyboardKey.escape): () => _sheet
382	            ? setState(() => _sheet = false)
383	            : run(_d.fullscreen ? widget.onFullscreen : null),
384	        const CharacterActivator('?'): _showShortcuts,
385	      },
386	      child: Focus(
387	        autofocus: true,
388	        child: MouseRegion(
389	          cursor: _chromeHidden ? SystemMouseCursors.none : MouseCursor.defer,
390	          onHover: (_) {
391	            _pointerSeen = true;
392	            _wake();
393	          },
394	          child: ColoredBox(
395	            color: WtColors.board,
396	            child: LayoutBuilder(
397	              builder: (context, box) {
398	                final compact = box.maxWidth < wtCompactWidth;
399	                return Stack(
400	                  children: [
401	                    if (_d.fullscreen)
402	                      _fullscreenLayout(compact: compact)
403	                    else
404	                      _windowLayout(compact: compact),
405	                    Positioned(
406	                      left: 0,
407	                      top: 0,
408	                      child: CompositedTransformFollower(
409	                        link: _playLink,
410	                        showWhenUnlinked: false,
411	                        targetAnchor: Alignment.topCenter,
412	                        followerAnchor: Alignment.bottomCenter,
413	                        // 12 px above the dock: the play button sits 12 px below its top edge.
414	                        offset: const Offset(0, -24),
415	                        child: AnimatedSwitcher(
416	                          duration: const Duration(milliseconds: 160),
417	                          switchInCurve: Curves.easeOutCubic,
418	                          transitionBuilder: (child, animation) =>
419	                              FadeTransition(
420	                                opacity: animation,
421	                                child: SlideTransition(
422	                                  position: Tween(
423	                                    begin: const Offset(0, 0.3),
424	                                    end: Offset.zero,
425	                                  ).animate(animation),
426	                                  child: child,
427	                                ),
428	                              ),
429	                          child: _toast && _d.pause != null && !_chromeHidden
430	                              ? _Toast(
431	                                  key: ValueKey(_d.pause!.serial),
432	                                  notice: _d.pause!,
433	                                  onResume: _d.connected ? widget.onPlay : null,
434	                                )
435	                              : const SizedBox.shrink(),
436	                        ),
437	                      ),
438	                    ),
439	                  ],
440	                );
441	              },
442	            ),
443	          ),
444	        ),
445	      ),
446	    );
447	  }
448	
449	  Widget _windowLayout({required bool compact}) => Column(
450	    children: [
451	      _topBar(compact: compact),
452	      if (!_d.connected) _banner(),
453	      Expanded(
454	        child: Stack(
455	          children: [
456	            Row(
457	              crossAxisAlignment: CrossAxisAlignment.stretch,
458	              children: [
459	                Expanded(child: _stageArea()),
460	                if (!compact) _Rail(data: _d, onAdd: widget.onAddToQueue),
461	              ],
462	            ),
463	            if (compact && _sheet) ...[
464	              Positioned.fill(
465	                child: GestureDetector(
466	                  behavior: HitTestBehavior.opaque,
467	                  onTap: () => setState(() => _sheet = false),
468	                  child: const ColoredBox(color: Color(0x8C000000)),
469	                ),
470	              ),
471	              Positioned(
472	                top: 0,
473	                right: 0,
474	                bottom: 0,
475	                child: DecoratedBox(
476	                  decoration: const BoxDecoration(
477	                    boxShadow: [
478	                      BoxShadow(
479	                        color: Color(0x99000000),
480	                        blurRadius: 40,
481	                        spreadRadius: -10,
482	                      ),
483	                    ],
484	                  ),
485	                  child: _Rail(data: _d, onAdd: widget.onAddToQueue),
486	                ),
487	              ),
488	            ],
489	          ],
490	        ),
491	      ),
492	      KeyedSubtree(key: roomDockKey, child: _dock(compact: compact)),
493	    ],
494	  );
495	
496	  /// The picture fills the screen; the dock and an exit button float over it and fade out
497	  /// while the pointer rests.
498	  Widget _fullscreenLayout({required bool compact}) {
499	    final hidden = _chromeHidden;
500	    Widget chrome(Widget child) => MouseRegion(
501	      onEnter: (_) => _chromeHover(true),
502	      onExit: (_) => _chromeHover(false),
503	      child: IgnorePointer(
504	        ignoring: hidden,
505	        child: AnimatedOpacity(
506	          opacity: hidden ? 0 : 1,
507	          duration: const Duration(milliseconds: 200),
508	          child: child,
509	        ),
510	      ),
511	    );
512	    return Column(
513	      children: [
514	        if (!_d.connected) _banner(),
515	        Expanded(
516	          child: Stack(
517	            children: [
518	              Positioned.fill(child: _stageArea()),
519	              Positioned(
520	                left: 0,
521	                right: 0,
522	                bottom: 0,
523	                child: chrome(
524	                  KeyedSubtree(key: roomDockKey, child: _dock(compact: compact)),
525	                ),
526	              ),
527	              Positioned(
528	                top: 16,
529	                right: 16,
530	                child: chrome(
531	                  WtButton(
532	                    label: 'Exit fullscreen',
533	                    icon: Icons.fullscreen_exit_rounded,
534	                    style: WtButtonStyle.ghost,
535	                    size: WtButtonSize.small,
536	                    tooltip: 'Exit fullscreen (Esc)',
537	                    onPressed: widget.onFullscreen,
538	                  ),
539	                ),
540	              ),
541	            ],
542	          ),
543	        ),
544	      ],
545	    );
546	  }
547	
548	  Widget _topBar({required bool compact}) {
549	    final total = _d.people.length;
550	    final ready = _d.readyCount;
551	    final allIn = total > 0 && ready >= total;
552	    return Container(
553	      height: 64,
554	      padding: const EdgeInsets.symmetric(horizontal: 16),
555	      decoration: const BoxDecoration(
556	        color: WtColors.plum2,
557	        border: Border(bottom: BorderSide(color: WtColors.line, width: 2)),
558	      ),
559	      child: Row(
560	        children: [
561	          WtIconButton(
562	            icon: Icons.arrow_back_rounded,
563	            tooltip: 'Leave room',
564	            onPressed: widget.onBack,
565	          ),
566	          const SizedBox(width: 14),
567	          if (compact) ...[
568	            Semantics(
569	              label: 'watch together',
570	              excludeSemantics: true,
571	              child: const WtMark(size: 32),
572	            ),
573	            const SizedBox(width: 12),
574	          ] else ...[
575	            const WtWordmark(size: 17, mark: 32),
576	            Container(
577	              width: 2,
578	              height: 24,
579	              margin: const EdgeInsets.symmetric(horizontal: 16),
580	              color: WtColors.line,
581	            ),
582	          ],
583	          Flexible(
584	            child: Text(
585	              _d.title,
586	              maxLines: 1,
587	              overflow: TextOverflow.ellipsis,
588	              style: const TextStyle(
589	                fontSize: 16,
590	                fontWeight: FontWeight.w800,
591	                color: WtColors.text,
592	              ),
593	            ),
594	          ),
595	          const SizedBox(width: 12),
596	          _RoomCode(code: _d.room),
597	          const SizedBox(width: 4),
598	          WtTextButton(
599	            label: _copied ? 'Copied' : 'Copy invite',
600	            icon: _copied ? Icons.check_rounded : Icons.copy_rounded,
601	            compact: true,
602	            onPressed: _copyInvite,
603	          ),
604	          const Spacer(),
605	          if (!compact) ...[
606	            WtTextButton(
607	              label: 'Shortcuts',
608	              icon: Icons.keyboard_rounded,
609	              color: WtColors.tx2,
610	              compact: true,
611	              onPressed: _showShortcuts,
612	            ),
613	            const SizedBox(width: 8),
614	          ],
615	          Tooltip(
616	            message: readyDetail(_d.people),
617	            child: Semantics(
618	              liveRegion: true,
619	              child: WtPill(
620	                label: readyPillLabel(ready, total),
621	                tone: allIn ? WtTone.live : WtTone.warn,
622	                dot: allIn ? WtDotStyle.solid : WtDotStyle.ring,
623	              ),
624	            ),
625	          ),
626	          const SizedBox(width: 12),
627	          if (compact) ...[
628	            WtIconButton(
629	              icon: Icons.people_alt_rounded,
630	              tooltip: _sheet ? 'Hide people and queue' : 'People and queue',
631	              background: _sheet ? WtColors.s2 : WtColors.s1,
632	              onPressed: () => setState(() => _sheet = !_sheet),
633	            ),
634	            const SizedBox(width: 12),
635	          ],
636	          WtIconButton(
637	            icon: Icons.settings_outlined,
638	            tooltip: 'Settings',
639	            onPressed: widget.onSettings,
640	          ),
641	        ],
642	      ),
643	    );
644	  }
645	
646	  Widget _banner() => Semantics(
647	    liveRegion: true,
648	    child: Container(
649	      height: 40,
650	      padding: const EdgeInsets.symmetric(horizontal: 24),
651	      decoration: const BoxDecoration(
652	        color: Color(0x1FFFD45E),
653	        border: Border(bottom: BorderSide(color: Color(0x66FFD45E), width: 2)),
654	      ),
655	      child: Row(
656	        mainAxisAlignment: MainAxisAlignment.center,
657	        children: [
658	          WtDot(
659	            color: WtColors.yellow,
660	            style: _d.disconnectReason == null
661	                ? WtDotStyle.pulse
662	                : WtDotStyle.ring,
663	          ),
664	          const SizedBox(width: 10),
665	          Flexible(
666	            child: Text(
667	              _d.disconnectReason != null
668	                  ? 'Disconnected: ${_d.disconnectReason}'
669	                  : _d.connecting
670	                  ? 'Connecting to the room…'
671	                  : 'Reconnecting… the room stays here; controls come back when we are.',
672	              maxLines: 1,
673	              overflow: TextOverflow.ellipsis,
674	              style: const TextStyle(
675	                fontSize: 14,
676	                fontWeight: FontWeight.w800,
677	                color: WtColors.yellow,
678	              ),
679	            ),
680	          ),
681	        ],
682	      ),
683	    ),
684	  );
685	
686	  Widget _stageArea() => WtBackdrop(
687	    color: WtColors.board,
688	    child: Padding(
