            'Nothing queued',
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w800,
              color: WtColors.text,
            ),
          ),
          SizedBox(height: 2),
          Text(
            'Add the next episode so nobody has to ask.',
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w600,
              color: WtColors.tx3,
            ),
          ),
        ],
      ),
    ),
  );
}

