23	/// `1.25×`, `0.5×`, `1×`.
24	String fmtSpeed(double rate) {
25	  final s = rate.toStringAsFixed(2).replaceFirst(RegExp(r'0+$'), '');
26	  return '${s.endsWith('.') ? s.substring(0, s.length - 1) : s}×';
