          const SizedBox(width: 14),
          if (compact) ...[
            Semantics(
              label: 'watch together',
              excludeSemantics: true,
              child: const WtMark(size: 32),
            ),
            const SizedBox(width: 12),
          ] else ...[
            const WtWordmark(size: 17, mark: 32),
            Container(
              width: 2,
              height: 24,
              margin: const EdgeInsets.symmetric(horizontal: 16),
