  Widget _banner() => Semantics(
    liveRegion: true,
    child: Container(
      height: 40,
      padding: const EdgeInsets.symmetric(horizontal: 24),
      decoration: const BoxDecoration(
        color: Color(0x1FFFD45E),
        border: Border(bottom: BorderSide(color: Color(0x66FFD45E), width: 2)),
