                bufferedMs: _d.bufferedMs,
                onSeek: _live ? widget.onSeekTo : null,
              ),
            ),
          ),
          const SizedBox(width: 16),
          if (_hasFile &&
              TrackMenu.hasChoice(_d.audioTracks, _d.subtitleTracks)) ...[
            TrackMenu(
