              subtitles: _d.subtitleTracks,
              onAudio: widget.onAudioTrack,
              onSubtitle: widget.onSubtitleTrack,
            ),
            const SizedBox(width: 8),
          ],
          VolumeControl(
            volume: _d.volume,
            muted: _d.muted,
