  _idleTimer?.cancel();
  if (!_d.fullscreen || !_pointerSeen || _pinned) return;
  _idleTimer = Timer(chromeHideAfter, () {
    if (!mounted || !_d.fullscreen || _pinned || _overChrome) return;
    setState(() => _idle = true);
