      height: 56,
      padding: const EdgeInsets.symmetric(horizontal: 8),
      decoration: warn
          ? BoxDecoration(
              color: const Color(0x12FFD45E),
              borderRadius: BorderRadius.circular(WtRadius.control),
            )
          : null,
      child: Row(
        children: [
          WtAvatar(
            id: p.id,
            name: p.name,
            muted: p.state == PersonState.reconnecting,
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Flexible(
                      child: Text(
                        p.name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.w800,
                          color: WtColors.text,
                        ),
                      ),
                    ),
                    if (p.you)
                      const Text(
                        ' (you)',
                        style: TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.w600,
                          color: WtColors.tx3,
                        ),
                      ),
                    if (p.host) ...[
                      const SizedBox(width: 8),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 6,
                          vertical: 1,
                        ),
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(6),
                          border: Border.all(color: WtColors.pink, width: 1.5),
                        ),
                        child: const Text(
                          'HOST',
                          style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 0.8,
                            color: WtColors.pink,
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
                const SizedBox(height: 2),
                Row(
                  children: [
                    WtDot(color: color, style: dot),
                    const SizedBox(width: 6),
                    Text(
                      p.status,
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                        color: warn ? WtColors.yellow : WtColors.tx3,
                      ),
                    ),
                  ],
                ),
