  });

  testWidgets('pause toast with Resume, then a Paused-by badge', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    var resumed = false;
    await pumpRoom(tester, video());
    await pumpRoom(
      tester,
      video(
        playing: false,
        pause: const PauseNotice(serial: 1, positionMs: 724000, by: 'Mika'),
      ),
