      await tester.pump(const Duration(milliseconds: 80));
      await tester.tapAt(picture);
      await tester.pump(kDoubleTapTimeout);
      expect(calls, ['pause', 'full']);

      await tester.tap(find.text('+10s'));
      await tester.pump(kDoubleTapTimeout);
